# Regenerated by scripts/update-homebrew-formula.sh for each release the formula follows.
# Edit that script, not this file, when the formula's structure needs to change.

class OxideCode < Formula
  desc "Terminal-based AI coding assistant written in Rust"
  homepage "https://github.com/hakula139/oxide-code"
  url "https://github.com/hakula139/oxide-code/releases/download/v0.1.0-alpha.3/oxide-code-x86_64-unknown-linux-gnu.tar.gz"
  version "0.1.0-alpha.3"
  sha256 "d1978c2d2af066e3aa9698ba873d654fa47dcd518cba1501dc48fd39192faa4d"
  license "MIT"

  # Every platform needs a URL for the arch requirements below to load and report.
  on_macos do
    depends_on arch: :arm64

    on_arm do
      url "https://github.com/hakula139/oxide-code/releases/download/v0.1.0-alpha.3/oxide-code-aarch64-apple-darwin.tar.gz"
      sha256 "f4a694bea83ff2ab0fa965a7942c9d168760eab94fc27dd024b816f60e75246a"
    end
  end

  on_linux do
    depends_on arch: :x86_64
  end

  def install
    bin.install "ox"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ox --version")
  end
end
